"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1754],{46326:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ShredderServer","desc":"Authoritative server script that owns the Workbench Shredder flow for\\nEndless Journey.\\n\\nOn `ReqShredderStart` the server validates workbench proximity, per-player\\ncooldown, and junk availability, then returns a hold duration computed by\\n`ShredderMath`. On `ReqShredderComplete` it re-validates proximity and\\ntiming (anti-exploit: elapsed \u2265 duration \u2212 tolerance), consumes all\\nWood/Metal junk Tools from the player\'s Backpack and equipped slot, computes\\nthe Wood/Metal yield via `JunkConfig.MaterialRules`, and credits it to the\\nserver-wide `MaterialPool`.\\n\\nThe pool broadcast carries the workbench\'s `TrajectoryPoints` arc endpoints;\\nevery client plays the arc + fly-to-HUD effect locally (see\\n`MaterialHudController`). No material Tools or floor pickups exist.","realm":["Server"],"source":{"line":35,"path":"src/ServerScriptService/ShredderServer.server.luau"}}')}}]);